#!/usr/bin/env node
/**
 * Build-time OG card generator.
 *
 * Produces:
 *   public/og/site.png          -- site-level card (1200x630)
 *   public/og/<slug>.png        -- one card per collection (10 total, 1200x630)
 *
 * Per-guide cards (public/og/<slug>-<id>.png) are NOT generated by default.
 * Set PELIGLOT_GENERATE_GUIDE_OG=1 to enable them (~313 extra images).
 * In-collection routes always point at the collection-level card at runtime.
 *
 * Caching:
 *   A content hash is computed per card from (title, oneliner, accentColor).
 *   If public/og/<key>.png already exists AND its sidecar
 *   public/og/.cache/<key>.hash matches the new hash, the card is skipped.
 *   On a fresh clone, all cards regenerate automatically.
 *
 * .gitignore note:
 *   /public/og/ is gitignored -- cards are generated at build time (prebuild).
 *   CI always gets fresh cards via `npm run build` -> prebuild hook.
 *   No manual steps needed; `git clone && npm ci && npm run build` is hermetic.
 *
 * Satori note:
 *   Every element with multiple children MUST have display:flex or display:block.
 *   We use plain object trees (no JSX, no React) for CJS compatibility.
 *   Emoji are NOT used -- Satori does not render color emoji (flag/pictograph
 *   emoji come through as missing-glyph boxes). Short text labels are used instead.
 *
 * Font fallback strategy:
 *   Satori does NOT fall back between two fonts registered with the same name.
 *   Latin-ext characters (macron vowels Ō/ā etc., ʻokina U+02BB) are handled by
 *   registering the latin-ext woff under a DISTINCT name ("Playfair Display Ext" /
 *   "Source Sans 3 Ext") and chaining in fontFamily strings.
 *   Arabic glyphs are handled by Cairo (cairo-arabic-700-normal.woff), chained
 *   after Playfair Display in the title fontFamily.
 *
 * Usage: node scripts/build-og-cards.cjs
 * Runs automatically as npm prebuild before `vite build`.
 */

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.resolve(__dirname, '..');
const SRC = path.join(ROOT, 'src');
const PUBLIC_OG = path.join(ROOT, 'public', 'og');
const CACHE_DIR = path.join(PUBLIC_OG, '.cache');

const CARD_W = 1200;
const CARD_H = 630;

// ---------------------------------------------------------------------------
// Font paths (hermetically resolved from node_modules -- no manual downloads)
// ---------------------------------------------------------------------------
const FONT_PLAYFAIR_BOLD = path.join(
  ROOT, 'node_modules', '@fontsource', 'playfair-display',
  'files', 'playfair-display-latin-700-normal.woff'
);
const FONT_PLAYFAIR_BOLD_EXT = path.join(
  ROOT, 'node_modules', '@fontsource', 'playfair-display',
  'files', 'playfair-display-latin-ext-700-normal.woff'
);
const FONT_SOURCE_SANS_REGULAR = path.join(
  ROOT, 'node_modules', '@fontsource', 'source-sans-3',
  'files', 'source-sans-3-latin-400-normal.woff'
);
const FONT_SOURCE_SANS_REGULAR_EXT = path.join(
  ROOT, 'node_modules', '@fontsource', 'source-sans-3',
  'files', 'source-sans-3-latin-ext-400-normal.woff'
);
const FONT_SOURCE_SANS_SEMIBOLD = path.join(
  ROOT, 'node_modules', '@fontsource', 'source-sans-3',
  'files', 'source-sans-3-latin-600-normal.woff'
);
const FONT_SOURCE_SANS_SEMIBOLD_EXT = path.join(
  ROOT, 'node_modules', '@fontsource', 'source-sans-3',
  'files', 'source-sans-3-latin-ext-600-normal.woff'
);
const FONT_CAIRO_BOLD = path.join(
  ROOT, 'node_modules', '@fontsource', 'cairo',
  'files', 'cairo-arabic-700-normal.woff'
);

// ---------------------------------------------------------------------------
// Per-collection theme.
// Accent colors match src/LandingPage.tsx card colors.
// For gradient cards, the second (bottom) stop is used when it produces a more
// distinctive identity — e.g. ai-interaction uses #6A1B9A (purple) because the
// first stop (#1565C0 blue) would be identical to english and math.
// Short text labels used in place of emoji (Satori can't render color emoji).
// ---------------------------------------------------------------------------
var COLLECTION_THEME = {
  spanish:          { label: 'ES',  accent: '#C62828', section: 'Languages' },
  arabic:           { label: 'AR',  accent: '#1B5E20', section: 'Languages' },
  english:          { label: 'EN',  accent: '#1565C0', section: 'Languages' },
  german:           { label: 'DE',  accent: '#1a1a1a', section: 'Languages' },
  hawaiian:         { label: 'HAW', accent: '#00695C', section: 'Languages' },
  music:            { label: 'MUS', accent: '#C62828', section: 'Beyond Language' },
  'jazz-guitar':    { label: 'JG',  accent: '#8D6E63', section: 'Beyond Language' },
  math:             { label: 'MTH', accent: '#1565C0', section: 'Beyond Language' },
  'ai-interaction': { label: 'AI',  accent: '#6A1B9A', section: 'Beyond Language' },
  freecad:          { label: 'CAD', accent: '#0d1b2a', section: 'Beyond Language' },
};

// Collection display titles.
// Latin-1 Supplement characters (é, ñ, etc.) work fine -- Playfair Display's
// "latin" subset covers U+0000-U+00FF.
// Hawaiian: ʻokina (U+02BB) and macron vowels (Ō, U+014C) are covered by the
// "latin-ext" subset registered as "Playfair Display Ext" (see font chain below).
// Arabic script (العربية): rendered via Cairo arabic-700 registered as "Cairo"
// and chained in the title fontFamily for the arabic collection.
var COLLECTION_TITLE = {
  spanish:          'Español',
  arabic:           'العربية',
  english:          'American English',
  german:           'Deutsch',
  hawaiian:         'ʻŌlelo Hawaiʻi',
  music:            'Music Theory',
  'jazz-guitar':    'Jazz Guitar',
  math:             'Math',
  'ai-interaction': 'AI Interaction',
  freecad:          'FreeCAD',
};

// ---------------------------------------------------------------------------
// Parse slugs from router.tsx (single source of truth)
// ---------------------------------------------------------------------------
function parseSlugs() {
  var content = fs.readFileSync(path.join(SRC, 'router.tsx'), 'utf-8');
  var match = content.match(/const guideSlugs\s*(?::[^=]+)?\s*=\s*\[([\s\S]*?)\]/);
  if (!match) throw new Error('Could not parse guideSlugs from src/router.tsx');
  var slugs = [];
  var re = /['"]([^'"]+)['"]/g;
  var m;
  while ((m = re.exec(match[1])) !== null) slugs.push(m[1]);
  if (!slugs.length) throw new Error('No slugs found in guideSlugs array');
  return slugs;
}

// ---------------------------------------------------------------------------
// Parse guide ids + titles from meta.ts (for per-guide cards).
//
// Backreference matches the opening delimiter so titles containing the OTHER
// quote characters survive. Without this, titles like "FreeCAD's Spreadsheet"
// truncated at the apostrophe — silent because per-guide cards are gated off
// by default. The escaped-character branch (\\.) lets a title use \" or \\
// inside a single- or backtick-delimited string.
// ---------------------------------------------------------------------------
function parseGuideMeta(slug) {
  var metaPath = path.join(SRC, 'guides', slug, 'meta.ts');
  if (!fs.existsSync(metaPath)) return [];
  var content = fs.readFileSync(metaPath, 'utf-8');
  var results = [];
  var re = /\{\s*id:\s*(\d+)[^}]*title:\s*(['"`])((?:\\.|(?!\2).)*)\2/g;
  var m;
  while ((m = re.exec(content)) !== null) {
    results.push({ id: parseInt(m[1], 10), title: m[3] });
  }
  return results;
}

// ---------------------------------------------------------------------------
// Parse collection one-liners from positioning.ts
// ---------------------------------------------------------------------------
function parseOneLiners() {
  var content = fs.readFileSync(path.join(SRC, 'copy', 'positioning.ts'), 'utf-8');
  var result = {};
  var slugs = [
    'spanish', 'arabic', 'english', 'german', 'hawaiian',
    'music', 'jazz-guitar', 'math', 'ai-interaction', 'freecad',
  ];
  for (var i = 0; i < slugs.length; i++) {
    var slug = slugs[i];
    var escapedSlug = slug.replace(/-/g, '[-]');
    // Keys may be unquoted (spanish:) or single/double quoted ('jazz-guitar':).
    // Capture the opening value-delimiter as a backreference so quotes inside
    // the value (e.g. "FreeCAD's") don't truncate the match.
    var re = new RegExp(
      "(?:['\"]" + escapedSlug + "['\"]|" + escapedSlug + ")\\s*:\\s*(['\"])((?:\\\\.|(?!\\1)[\\s\\S])*)\\1\\s*[,}]"
    );
    var m = content.match(re);
    if (m) {
      result[slug] = m[2].replace(/\s+/g, ' ').trim();
    }
  }
  return result;
}

// ---------------------------------------------------------------------------
// Caching helpers
// ---------------------------------------------------------------------------
function computeHash(data) {
  return crypto.createHash('sha256').update(JSON.stringify(data)).digest('hex').slice(0, 16);
}

function readCachedHash(key) {
  var p = path.join(CACHE_DIR, key + '.hash');
  if (!fs.existsSync(p)) return null;
  return fs.readFileSync(p, 'utf-8').trim();
}

function writeCachedHash(key, hash) {
  if (!fs.existsSync(CACHE_DIR)) fs.mkdirSync(CACHE_DIR, { recursive: true });
  fs.writeFileSync(path.join(CACHE_DIR, key + '.hash'), hash, 'utf-8');
}

function isCacheValid(key, hash) {
  var pngPath = path.join(PUBLIC_OG, key + '.png');
  if (!fs.existsSync(pngPath)) return false;
  // Both the PNG AND a matching hash sidecar must exist
  return readCachedHash(key) === hash;
}

// ---------------------------------------------------------------------------
// Satori tree builders.
// Rules for Satori:
//   - Every element with multiple children needs display:flex or display:block.
//   - Use plain objects, not JSX.
//   - Leaf text can be a string child directly.
// ---------------------------------------------------------------------------

function el(tag, style, children) {
  return { type: tag, props: { style: style, children: children } };
}

function txt(text, style) {
  return el('div', style, text);
}

// Spacer div with accent color (left bar)
function accentBar(color, width) {
  return el('div', { width: width, background: color, flexShrink: 0 }, '');
}

function statPill(value, label) {
  return el('div', { display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }, [
    txt(value, {
      fontFamily: '"Playfair Display", "Cairo", "Playfair Display Ext"',
      fontWeight: 700,
      fontSize: 28,
      color: '#2E4057',
    }),
    txt(label, {
      fontFamily: '"Source Sans 3", "Source Sans 3 Ext"',
      fontSize: 14,
      fontWeight: 400,
      color: '#888888',
      textTransform: 'uppercase',
      letterSpacing: '0.5px',
    }),
  ]);
}

function badge(text, accentColor) {
  return txt(text, {
    fontFamily: '"Source Sans 3", "Source Sans 3 Ext"',
    fontSize: 13,
    fontWeight: 600,
    color: '#ffffff',
    background: accentColor,
    padding: '4px 12px',
    borderRadius: 4,
    letterSpacing: '0.5px',
  });
}

function buildSiteCard(tagline, heroPitch) {
  return el('div', { width: '100%', height: '100%', display: 'flex', fontFamily: '"Source Sans 3", "Source Sans 3 Ext"', background: '#ffffff' }, [
    accentBar('#2E4057', 12),
    el('div', {
      flex: 1,
      display: 'flex',
      flexDirection: 'column',
      padding: '56px 64px 48px 56px',
      justifyContent: 'space-between',
    }, [
      // Top: wordmark + tagline
      el('div', { display: 'flex', flexDirection: 'column', gap: 20 }, [
        txt('Peliglot', {
          fontFamily: '"Playfair Display", "Cairo", "Playfair Display Ext"',
          fontWeight: 700,
          fontSize: 56,
          color: '#1a1a1a',
          letterSpacing: '-0.5px',
        }),
        txt(tagline, {
          fontFamily: '"Source Sans 3", "Source Sans 3 Ext"',
          fontSize: 24,
          fontWeight: 400,
          color: '#555555',
          lineHeight: 1.4,
          maxWidth: 820,
        }),
      ]),
      // Bottom: hero pitch + stat row
      el('div', { display: 'flex', flexDirection: 'column', gap: 24 }, [
        txt(heroPitch, {
          fontFamily: '"Source Sans 3", "Source Sans 3 Ext"',
          fontSize: 20,
          fontWeight: 600,
          color: '#1a1a1a',
          lineHeight: 1.5,
          maxWidth: 820,
        }),
        el('div', { display: 'flex', gap: 40 }, [
          statPill('10', 'collections'),
          statPill('300+', 'guides'),
          statPill('Free', 'no ads'),
        ]),
      ]),
    ]),
  ]);
}

function buildCollectionCard(slug, title, oneLiner, accentColor, sectionLabel, shortLabel) {
  return el('div', { width: '100%', height: '100%', display: 'flex', fontFamily: '"Source Sans 3", "Source Sans 3 Ext"', background: '#ffffff' }, [
    accentBar(accentColor, 16),
    el('div', {
      flex: 1,
      display: 'flex',
      flexDirection: 'column',
      padding: '52px 64px 48px 52px',
      justifyContent: 'space-between',
    }, [
      // Top: badge row + title
      el('div', { display: 'flex', flexDirection: 'column', gap: 24 }, [
        // Badge row
        el('div', { display: 'flex', alignItems: 'center', gap: 16 }, [
          badge(shortLabel, accentColor),
          txt(sectionLabel, {
            fontFamily: '"Source Sans 3", "Source Sans 3 Ext"',
            fontSize: 14,
            fontWeight: 400,
            color: '#888888',
            letterSpacing: '0.3px',
            textTransform: 'uppercase',
          }),
        ]),
        // Collection title
        txt(title, {
          fontFamily: '"Playfair Display", "Cairo", "Playfair Display Ext"',
          fontWeight: 700,
          fontSize: 64,
          color: '#1a1a1a',
          letterSpacing: '-0.5px',
          lineHeight: 1.1,
        }),
      ]),
      // Bottom: one-liner + wordmark
      el('div', { display: 'flex', flexDirection: 'column', gap: 20 }, [
        txt(oneLiner, {
          fontFamily: '"Source Sans 3", "Source Sans 3 Ext"',
          fontSize: 22,
          fontWeight: 400,
          color: '#444444',
          lineHeight: 1.5,
          maxWidth: 900,
        }),
        el('div', { display: 'flex', justifyContent: 'flex-end' }, [
          txt('Peliglot', {
            fontFamily: '"Playfair Display", "Cairo", "Playfair Display Ext"',
            fontWeight: 700,
            fontSize: 20,
            color: '#aaaaaa',
          }),
        ]),
      ]),
    ]),
  ]);
}

function buildGuideCard(guideTitle, collectionTitle, accentColor, shortLabel) {
  return el('div', { width: '100%', height: '100%', display: 'flex', fontFamily: '"Source Sans 3", "Source Sans 3 Ext"', background: '#ffffff' }, [
    accentBar(accentColor, 12),
    el('div', {
      flex: 1,
      display: 'flex',
      flexDirection: 'column',
      padding: '56px 64px 48px 52px',
      justifyContent: 'space-between',
    }, [
      el('div', { display: 'flex', flexDirection: 'column', gap: 28 }, [
        el('div', { display: 'flex', alignItems: 'center', gap: 12 }, [
          badge(shortLabel, accentColor),
          txt(collectionTitle, {
            fontFamily: '"Source Sans 3", "Source Sans 3 Ext"',
            fontSize: 15,
            color: '#888888',
          }),
        ]),
        txt(guideTitle, {
          fontFamily: '"Playfair Display", "Cairo", "Playfair Display Ext"',
          fontWeight: 700,
          fontSize: 58,
          color: '#1a1a1a',
          lineHeight: 1.15,
          letterSpacing: '-0.3px',
          maxWidth: 900,
        }),
      ]),
      el('div', { display: 'flex', justifyContent: 'flex-end' }, [
        txt('Peliglot', {
          fontFamily: '"Playfair Display", "Cairo", "Playfair Display Ext"',
          fontWeight: 700,
          fontSize: 20,
          color: '#aaaaaa',
        }),
      ]),
    ]),
  ]);
}

// ---------------------------------------------------------------------------
// Render a Satori tree to PNG
// ---------------------------------------------------------------------------
async function renderToPng(tree, fonts) {
  var satoriModule = require('satori');
  var satori = satoriModule.default;
  var resvgJs = require('@resvg/resvg-js');
  var Resvg = resvgJs.Resvg;

  var svg = await satori(tree, { width: CARD_W, height: CARD_H, fonts: fonts });
  var resvg = new Resvg(svg, { fitTo: { mode: 'width', value: CARD_W } });
  return resvg.render().asPng();
}

// ---------------------------------------------------------------------------
// Write PNG with cache bookkeeping
// ---------------------------------------------------------------------------
function writePng(key, pngBuffer, hashValue) {
  var outPath = path.join(PUBLIC_OG, key + '.png');
  fs.writeFileSync(outPath, pngBuffer);
  writeCachedHash(key, hashValue);
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
async function main() {
  if (!fs.existsSync(PUBLIC_OG)) fs.mkdirSync(PUBLIC_OG, { recursive: true });
  if (!fs.existsSync(CACHE_DIR)) fs.mkdirSync(CACHE_DIR, { recursive: true });

  // Load fonts once.
  // Satori does NOT fall back between two fonts with the same name; latin-ext
  // and Arabic fonts are therefore registered under distinct names and chained
  // via fontFamily strings throughout the card builders.
  var fonts = [
    {
      name: 'Playfair Display',
      data: fs.readFileSync(FONT_PLAYFAIR_BOLD),
      weight: 700,
      style: 'normal',
    },
    {
      name: 'Playfair Display Ext',
      data: fs.readFileSync(FONT_PLAYFAIR_BOLD_EXT),
      weight: 700,
      style: 'normal',
    },
    {
      name: 'Source Sans 3',
      data: fs.readFileSync(FONT_SOURCE_SANS_REGULAR),
      weight: 400,
      style: 'normal',
    },
    {
      name: 'Source Sans 3 Ext',
      data: fs.readFileSync(FONT_SOURCE_SANS_REGULAR_EXT),
      weight: 400,
      style: 'normal',
    },
    {
      name: 'Source Sans 3',
      data: fs.readFileSync(FONT_SOURCE_SANS_SEMIBOLD),
      weight: 600,
      style: 'normal',
    },
    {
      name: 'Source Sans 3 Ext',
      data: fs.readFileSync(FONT_SOURCE_SANS_SEMIBOLD_EXT),
      weight: 600,
      style: 'normal',
    },
    {
      name: 'Cairo',
      data: fs.readFileSync(FONT_CAIRO_BOLD),
      weight: 700,
      style: 'normal',
    },
  ];

  var slugs = parseSlugs();
  var oneLiners = parseOneLiners();

  var generated = 0;
  var skipped = 0;

  console.log('Generating OG cards...');

  // ---- Site card ----
  var siteTagline =
    'Hand-crafted interactive guides for languages and more. No ads, no accounts.';
  var siteHeroPitch =
    'Ten collections. Over 300 guides. Built by one person who wanted to learn, not to be marketed to.';

  var siteHash = computeHash({ siteTagline: siteTagline, siteHeroPitch: siteHeroPitch, v: 3 });
  if (isCacheValid('site', siteHash)) {
    console.log('  [skip] site.png (unchanged)');
    skipped++;
  } else {
    var siteTree = buildSiteCard(siteTagline, siteHeroPitch);
    var sitePng = await renderToPng(siteTree, fonts);
    writePng('site', sitePng, siteHash);
    console.log('  [gen]  site.png (' + sitePng.length + ' bytes)');
    generated++;
  }

  // ---- Collection cards ----
  for (var i = 0; i < slugs.length; i++) {
    var slug = slugs[i];
    var theme = COLLECTION_THEME[slug];
    if (!theme) {
      console.warn('  [warn] No theme for slug: ' + slug + ' -- skipping');
      continue;
    }
    var title = COLLECTION_TITLE[slug] || slug;
    var oneLiner = oneLiners[slug] || '';
    var hash = computeHash({
      slug: slug,
      title: title,
      oneLiner: oneLiner,
      accent: theme.accent,
      label: theme.label,
      section: theme.section,
      v: 3,
    });

    if (isCacheValid(slug, hash)) {
      console.log('  [skip] ' + slug + '.png (unchanged)');
      skipped++;
    } else {
      var tree = buildCollectionCard(slug, title, oneLiner, theme.accent, theme.section, theme.label);
      var png = await renderToPng(tree, fonts);
      writePng(slug, png, hash);
      console.log('  [gen]  ' + slug + '.png (' + png.length + ' bytes)');
      generated++;
    }
  }

  // ---- Per-guide cards (optional) ----
  if (process.env.PELIGLOT_GENERATE_GUIDE_OG === '1') {
    console.log('\nGenerating per-guide cards (PELIGLOT_GENERATE_GUIDE_OG=1)...');
    for (var j = 0; j < slugs.length; j++) {
      var gSlug = slugs[j];
      var gTheme = COLLECTION_THEME[gSlug];
      if (!gTheme) continue;
      var collTitle = COLLECTION_TITLE[gSlug] || gSlug;
      var guides = parseGuideMeta(gSlug);
      for (var k = 0; k < guides.length; k++) {
        var g = guides[k];
        var gKey = gSlug + '-' + g.id;
        var gHash = computeHash({ slug: gSlug, id: g.id, title: g.title, accent: gTheme.accent, v: 3 });
        if (isCacheValid(gKey, gHash)) { skipped++; continue; }
        var gTree = buildGuideCard(g.title, collTitle, gTheme.accent, gTheme.label);
        var gPng = await renderToPng(gTree, fonts);
        writePng(gKey, gPng, gHash);
        console.log('  [gen]  ' + gKey + '.png');
        generated++;
      }
    }
  }

  console.log('\nOG cards: ' + generated + ' generated, ' + skipped + ' skipped (cached).');
  console.log('Output: ' + PUBLIC_OG);
}

main().catch(function(err) {
  console.error('ERROR in build-og-cards:', err);
  process.exit(1);
});
